  type ReviewFinding,
  type RunDetail,
  type RunScope,
  type WorkerResult,
} from './api.ts'
import { capturedFiles, fileAnchorId, isMarkdownPath, NOT_CAPTURED_WORDING, notCapturedFiles, recordsCapture, type CapturedFile } from './files.ts'
import { findingsForFile, linesNamed } from './findings.ts'
import { ErrorPanel, LoadingPanel } from './panels.tsx'
import { keepInView } from './scroll.ts'
import { useResource, type Resource } from './useResource.ts'

type SnapshotNode = RunDetail['snapshot']['nodes'][number]
type Range = [number, number]

type Props = {
  scope: RunScope
  result: WorkerResult
  /** The run's review node, whose recorded findings are shown on the files they name; null when the graph has none. */
  reviewNode: SnapshotNode | null
  refreshToken: number
  /** A captured file to scroll to, handed over by a review finding's file link; null otherwise. */
  focusPath: string | null
  onFocusApplied: () => void
}

/** The review a finding list comes from, the same way the review node finds it; null when none is recorded. */
function reviewPathOf(scope: RunScope, node: SnapshotNode | null): string | null {
  if (node === null) return null
  if (node.result_uri !== null) return scopedReviewPath(scope, node.result_uri)
  return node.status === 'pending' ? null : paths.review(scope, Math.max(node.attempt, 1))
}

function rangeText([from, to]: Range): string {
  return from === to ? `line ${from}` : `lines ${from}–${to}`
}

/** The review findings that name this file: severity, reviewer, disposition and message, and a control to mark the lines a finding names. */
function FileFindings({ findings, path, onShowLines }: { findings: Resource<ReviewFinding[] | null>; path: string; onShowLines: (ranges: Range[]) => void }) {
  if (findings.status === 'idle') return <p className="projects-muted" data-testid="file-findings-no-review">No review is recorded for this run, so no findings are shown on its files.</p>
  if (findings.status === 'loading') return <LoadingPanel>Loading the review findings…</LoadingPanel>
  if (findings.status === 'error') return <p className="projects-error-inline" role="alert">The recorded review could not be loaded, so findings on this file are not shown.</p>
  if (findings.data === null) return <p className="projects-muted" data-testid="file-findings-no-review">No review is recorded for this run, so no findings are shown on its files.</p>
  const named = findingsForFile(findings.data, path)
  if (named.length === 0) return <p className="projects-muted" data-testid="file-findings-none">No review finding names this file.</p>
  return (
    <ul className="evidence-list" data-testid="file-findings">
      {named.map((finding, index) => {
        const ranges = linesNamed(finding.message, path)
        return (
          <li key={index} data-testid="file-finding" data-severity={finding.severity} data-reviewer={finding.reviewer} data-disposition={finding.disposition}>
            <span className="finding-severity">{finding.severity}</span>
            {' '}· <span data-testid="file-finding-reviewer">{finding.reviewer}</span> · {finding.disposition} — {finding.message}
            {ranges.length > 0 && (
              <>
                {' '}
                <button type="button" className="button button-small" data-testid="show-lines" onClick={() => onShowLines(ranges)}>
                  Show {ranges.map(rangeText).join(', ')}
                </button>
              </>
            )}
          </li>
        )
      })}
    </ul>
  )
}

/** The exact file content, one element per line; lines a finding names are marked. */
function FileSource({ text, marked, preRef }: { text: string; marked: Range[]; preRef: RefObject<HTMLPreElement | null> }) {
  const lines = text.endsWith('\n') ? text.slice(0, -1).split('\n') : text.split('\n')
  const isMarked = (line: number) => marked.some(([from, to]) => line >= from && line <= to)
  )
}

/**
 * "Files created or changed" on a launch node: every changed file of the result in order, captured ones with their content
 * and the findings that name them, the others with the reason they were not captured. A result recorded before capture
 * lists the paths and says the files were not captured.
 */
export function CreatedFiles({ scope, result, reviewNode, refreshToken, focusPath, onFocusApplied }: Props) {
  const captured = capturedFiles(result)
  const byPath = new Map(captured.map(file => [file.path, file]))
  const reasons = new Map(notCapturedFiles(result).map(entry => [entry.path, entry.reason]))
  const recorded = recordsCapture(result)
  // Every changed file in the result's order, then any captured or listed path the changed files do not name (never dropped).
  const listed = [...result.changed_files]
  for (const path of [...byPath.keys(), ...reasons.keys()]) if (!listed.includes(path)) listed.push(path)

  const reviewPath = captured.length === 0 ? null : reviewPathOf(scope, reviewNode)
  const loadReview = useCallback(
    (signal: AbortSignal) => orNotRecorded(fetchReviewResult(scope, reviewPath!, signal), NOT_RECORDED.review).then(review => review?.findings ?? null),
    [scope, reviewPath],
  )
  const { state: findings } = useResource(reviewPath, loadReview, refreshToken)

  // A file link is applied once: the target panel scrolls into view when it mounts, and the run view forgets the hand-over.
  const [focus] = useState(() => focusPath)
  useEffect(() => {
    if (focus !== null) onFocusApplied()
  }, [focus, onFocusApplied])

  return (
    <section className="evidence-section" aria-labelledby="evidence-created-files" data-testid="created-files" data-captured={captured.length}>
      <h4 id="evidence-created-files">Files created or changed</h4>
      {listed.length === 0 ? (
        <p className="projects-muted" data-testid="changed-files-empty">No changed files were recorded.</p>
      ) : (
        <>
          {!recorded && (
            <p className="projects-muted" data-testid="files-not-captured">
              Created files were not captured for this run (its results predate file capture), so only their paths are listed.
            </p>
    if (result.run_id !== scope.runId) throw new Error(`the result belongs to run ${result.run_id}.`)
    return result
  }, signal)
}

/** Text artifacts (logs, reports, patches) are read as plain text and rendered as text, never as HTML. */
export async function fetchArtifactText(scope: RunScope, artifactId: string, signal?: AbortSignal): Promise<string> {
  const response = await request(paths.artifact(scope, artifactId), signal, 'text/plain, */*')
  return response.text()
}

/** Only reviews published under this run's scoped `reviews/` route are fetched; anything else is refused. */
export function scopedReviewPath(scope: RunScope, resultUri: string): string | null {
  const prefix = `${paths.run(scope)}/reviews/`
  if (!resultUri.startsWith(prefix)) return null
  if (!/^[1-9][0-9]*$/.test(resultUri.slice(prefix.length))) return null
  return resultUri
}

export function fetchReviewResult(scope: RunScope, reviewPath: string, signal?: AbortSignal): Promise<ReviewResult> {
  return requestJson(reviewPath, input => {
    const review = validateReviewResult(input)
    if (review.run_id !== scope.runId) throw new Error(`the review belongs to run ${review.run_id}.`)
    return review
  }, signal)
}

export function fetchRunInputs(scope: RunScope, signal?: AbortSignal): Promise<RunInputs> {
  return requestJson(paths.inputs(scope), input => {
    const inputs = validateRunInputs(input)
    if (inputs.run_id !== scope.runId) throw new Error(`the inputs belong to run ${inputs.run_id}.`)

    const worker = map.workerOf.get(node.node_id)
    const workerPacket = worker ? latestPacket('worker', worker) : undefined
    let attempt = 0
    let session_id: string | null = null
    let result_uri: string | null = null
    if (worker) {
      if (workerPacket) {
        attempt = map.verifyNodes.has(node.node_id) ? workerPacket.attempt : 1
        result_uri = resultRoute(scope, state.run_id, 'worker', worker, workerPacket.attempt)
        const session = workerPacket.ok ? workerPacket.result.session_id : null
        session_id = typeof session === 'string' && session.length > 0 ? session : null
      }
      if (!map.verifyNodes.has(node.node_id)) {
        const receipt = laneValue(state.values, worker, 'launch')
        const session = receipt && typeof receipt === 'object' ? (receipt as Record<string, unknown>).session_id : null
        if (typeof session === 'string' && session.length > 0) session_id = session
      }
    }
    if (node.node_id === 'candidate') attempt = Math.max(0, ...packets.filter(packet => packet.phase === 'candidate').map(packet => packet.attempt))
    if (map.verifyNodes.has(node.node_id)) attempt = Math.max(attempt, eventAttempt.get(node.node_id) ?? 0)
    // The review node names its reviewer and links to the recorded result only from the export's review section, never from `values`.
    if (node.node_id === 'review' && state.review) {
      attempt = state.review.attempt
      session_id = redactPaths(state.review.reviewer_session_id)
      result_uri = reviewRoute(scope, state.run_id, state.review.attempt)
    }
    let status: NodeStatus
    const event = lastEvent.get(node.node_id)
    const eventStatus = event ? EVENT_STATUS[event.status] ?? null : null
    // The design challenge node is decided by the export's challenge record when there is one, never by `values`.
    const challenge = node.node_id === CHALLENGE_NODE ? state.inputs?.challenge ?? null : null
    if (challenge) { attempt = challenge.attempts; session_id = challenge.session_id }
    if (challenge?.status === 'paused') status = 'paused'
    else if (challenge) status = 'succeeded'
    else if (task?.error) status = 'failed'
    else if (task && task.interrupts.length > 0) status = 'awaiting_approval'
    else if (hasEvidence(state, node.node_id, map)) {
      if (map.verifyNodes.has(node.node_id)) status = workerPacket?.ok && workerPacket.gate.status === 'passed' ? 'succeeded' : 'paused'
      else if (node.node_id === 'candidate') {
        const latest = [...workers].map(candidate => latestPacket('candidate', candidate)).filter(packet => packet !== undefined)
        status = latest.length > 0 && latest.every(packet => packet.ok && packet.gate.status === 'passed') ? 'succeeded' : 'paused'
      } else status = 'succeeded'
    } else if (eventStatus === 'succeeded') status = evidenced ? 'paused' : 'succeeded'
    else if (eventStatus) status = eventStatus
    else status = 'pending'
    if (status !== 'pending' && attempt === 0) attempt = 1
    if (status === 'pending') { attempt = 0; session_id = null; result_uri = null }
    // The combined candidate holds one verified result per lane; link each so its evidence (screenshots included) is reachable.
    const lane_results = node.node_id === 'candidate' && status !== 'pending'
      ? map.lanes.flatMap(lane => {
        const packet = latestPacket('candidate', lane)
        return packet ? [{ worker: lane, attempt: packet.attempt, result_uri: resultRoute(scope, state.run_id, 'candidate', lane, packet.attempt) }] : []
      })
      : []
    return { node_id: node.node_id, kind: node.kind, depends_on: [...node.depends_on], status, attempt, session_id, result_uri, lane_results }
  })
  const statuses = new Set(nodes.map(node => node.status))
  const integrated = hasEvidence(state, 'integrate', map)
  let status: NodeStatus
  if (statuses.has('failed')) status = 'failed'
  else if (statuses.has('awaiting_approval')) status = 'awaiting_approval'
  else if (statuses.has('paused')) status = 'paused'
  else if (integrated && state.next.length === 0 && !statuses.has('running') && !statuses.has('pending')) status = 'succeeded'
  else if (integrated) status = 'paused'
  else if (statuses.has('running') || state.next.length > 0) status = 'running'
  else if (statuses.size === 1 && statuses.has('pending')) status = 'pending'
  else status = 'paused'
  return { contract_version: '1.0.0', run_id: state.run_id, status, last_sequence: rawEvents.at(-1)?.sequence ?? 0, nodes }
}

/** Publishes a verified packet's result: scoped artifact links, no worktree paths, and a failed status when the gate did not pass. */
function projectWorkerResult(scope: Scope, runId: string, nodeId: string, packet: LoadedPacket & { ok: true }): WorkerResult {
  const raw = packet.result
  if (raw.run_id !== runId || raw.node_id !== packet.node_id || raw.attempt !== packet.attempt) {
    throw new ProjectApiError(500, 'EVIDENCE_MISMATCH', 'The verification packet result does not match its registration.')
  }
  const passed = packet.gate.status === 'passed'
  const checks = Array.isArray(raw.checks) ? (raw.checks as Record<string, unknown>[]).map(check => ({ ...check, cwd: `verification/${packet.phase}/${packet.node_id}/${packet.attempt}/worktree` })) : raw.checks
  const artifacts = Array.isArray(raw.artifacts) ? (raw.artifacts as Record<string, unknown>[]).map(artifact => ({
    ...artifact, uri: typeof artifact.artifact_id === 'string' ? `${runRoute(scope, runId)}/artifacts/${encodeURIComponent(artifact.artifact_id)}` : artifact.uri,
  })) : raw.artifacts
  const assumptions = Array.isArray(raw.open_assumptions) ? raw.open_assumptions.filter(item => typeof item === 'string' && item.trim().length > 0) : raw.open_assumptions
  const candidate = {
    contract_version: '1.0.0', run_id: runId, node_id: nodeId, attempt: packet.attempt, session_id: raw.session_id,
    status: passed ? raw.status : 'failed', base_commit: raw.base_commit, output_commit: raw.output_commit,
    changed_files: raw.changed_files, checks, open_assumptions: assumptions, artifacts,
    ...(packet.deferred.length > 0 ? { deferred_checks: packet.deferred } : {}),
    // Worker-phase captures list the changed paths not copied as `file` artifacts; older and candidate-phase results carry none.
    ...(raw.files_not_captured !== undefined ? { files_not_captured: raw.files_not_captured } : {}),
    summary: typeof raw.summary === 'string' ? redactPaths(raw.summary) : raw.summary,
    error: passed ? raw.error : { code: 'VERIFICATION_BLOCKED', message: redactPaths(packet.gate.reasons.join('; ')) || 'Verification did not pass.', retryable: true },

  }, 12),
  [RUN_ONE_LANE]: runDetail(RUN_ONE_LANE, 'succeeded', ONE_LANE_DEFINITION, T2, T3, {
    ...lanesVerified(ONE_LANE), review: { status: 'succeeded', attempt: 1, session: REVIEWER_SESSION, review: 1 }, approval: done(), integrate: done(),
  }, 8),
  // A snapshot node holds one session id, so the review node names the first declared reviewer's; every reviewer is listed in the review result itself.
  [RUN_TWO_REVIEWERS]: runDetail(RUN_TWO_REVIEWERS, 'succeeded', REVIEWERS_DEFINITION, T1, T3, {
    ...lanesVerified(TWO_LANES), review: { status: 'succeeded', attempt: 1, session: GENERAL_REVIEWER_SESSION, review: 1 }, approval: done(), integrate: done(),
  }, 11),
  [RUN_REVIEWER_BLOCKED]: runDetail(RUN_REVIEWER_BLOCKED, 'failed', REVIEWERS_DEFINITION, T2, T3, {
    ...lanesVerified(TWO_LANES), review: { status: 'failed', attempt: 1, session: GENERAL_REVIEWER_SESSION, review: 1 },
  }, 9),
  [RUN_LEGACY_REVIEWER]: runDetail(RUN_LEGACY_REVIEWER, 'succeeded', REVIEWERS_DEFINITION, T0, T2, {
    ...lanesVerified(TWO_LANES), review: { status: 'succeeded', attempt: 1, session: LEGACY_REVIEWER_SESSION, review: 1 }, approval: done(), integrate: done(),
  }, 9),
  [RUN_FILES]: runDetail(RUN_FILES, 'succeeded', CLARITY_DEFINITION, T1, T3, {
    ...lanesVerified(TWO_LANES), review: { status: 'succeeded', attempt: 1, session: GENERAL_REVIEWER_SESSION, review: 1 }, approval: done(), integrate: done(),
  }, 6),
  // The challenge was accepted; ui verified; the adapter's verification failed and its worker is fixing it, waiting on an answer.
  [RUN_GUARDED]: runDetail(RUN_GUARDED, 'running', GUARDED_DEFINITION, T1, T3, {
    challenge: done(),
    launch_ui: done(UI_SESSION, 'ui'), launch_adapter: done(ADAPTER_SESSION, 'adapter'), handoff: done(),
    verify_ui: done(undefined, 'ui'), verify_adapter: { status: 'running', attempt: 1, result: 'adapter' },
  }, 9),
}

/** Each workflow's runs sorted by `updated_at` descending then `run_id` ascending, as the contract requires. */
export const runLists: Record<string, { runs: RunDetail['summary'][]; next_cursor: null }> = Object.fromEntries([WORKFLOW_ID, LANES_WORKFLOW_ID, REVIEWERS_WORKFLOW_ID, CLARITY_WORKFLOW_ID, GUARDED_WORKFLOW_ID].map(workflowId => [workflowId, {
  runs: Object.values(runDetails).map(detail => detail.summary).filter(summary => summary.workflow_id === workflowId)
    .sort((a, b) => b.updated_at.localeCompare(a.updated_at) || a.run_id.localeCompare(b.run_id)),
  next_cursor: null,
}]))

/** The combined candidate's per-lane results, served under `results/candidate_<lane>/<attempt>` like the real adapter. */
const candidateResults = (runId: string, lanes: readonly string[]) => Object.fromEntries(lanes.map(lane => [`candidate_${lane}/1`, laneResult(lane, runId)]))

export const workerResults: Record<string, Record<string, WorkerResult>> = {
  [RUN_SUCCEEDED]: { 'ui/1': uiResult(RUN_SUCCEEDED), 'adapter/1': adapterResult(RUN_SUCCEEDED, false), ...candidateResults(RUN_SUCCEEDED, ['ui', 'adapter']) },
  [RUN_FAILED]: { 'ui/1': uiResult(RUN_FAILED), 'ui/2': { ...uiResult(RUN_FAILED), attempt: 2 }, 'adapter/1': adapterResult(RUN_FAILED, true) },
  [RUN_AWAITING]: { 'ui/1': uiResult(RUN_AWAITING), 'adapter/1': adapterResult(RUN_AWAITING, false), ...candidateResults(RUN_AWAITING, ['ui', 'adapter']) },
